$('loginForm').addEventListener('submit',async event=>{event.preventDefault();$('loginError').textContent='';try{const path=needsSetup?'/api/control-center/setup':'/api/control-center/login';const result=await authRequest(path,{method:'POST',body:JSON.stringify({username:$('loginUser').value,password:$('loginPassword').value})});needsSetup=false;$('loginPassword').value='';showApplication(result.user)}catch(error){$('loginError').textContent=String(error)}});$('logout').addEventListener('click',async()=>{await authRequest('/api/control-center/logout',{method:'POST'}).catch(()=>{});showLogin()});$('theme').addEventListener('change',event=>{localStorage.setItem('wentian-theme',event.target.value);document.documentElement.dataset.theme=event.target.value});$('language').addEventListener('change',event=>{localStorage.setItem('wentian-language',event.target.value);applyPreferences()});applyPreferences();authRequest('/api/control-center/status').then(status=>{needsSetup=status.needsSetup;if(needsSetup){document.querySelector('#loginForm button').textContent='初期管理者を作成';$('loginError').textContent='12文字以上のパスワードを設定してください。'}return authRequest('/api/control-center/me')}).then(result=>showApplication(result.user)).catch(showLogin);
const externalPanel=$('externalAgents').closest('.panel');externalPanel.querySelector('p').textContent='ローカルCLIを10秒ごとに実測し、リアルタイム状態として表示します。';const registerBox=document.createElement('div');registerBox.innerHTML='<div class="controls"><input id="agentId" placeholder="ID（例: my-agent）"><input id="agentName" placeholder="表示名"><input id="agentCli" placeholder="CLI名"><input id="agentRepo" placeholder="GitHub owner/repository（任意）"><button id="agentRegister" type="button">手動登録</button></div><pre id="agentRegisterResult" class="muted"></pre>';$('marketplace').closest('.panel').insertBefore(registerBox,$('marketplace'));
const array=value=>Array.isArray(value)?value:Array.isArray(value?.data)?value.data:[];
const pick=(obj,paths,fallback='—')=>{for(const path of paths){let value=obj;for(const key of path.split('.'))value=value?.[key];if(value!==undefined&&value!==null)return value}return fallback};
const num=value=>typeof value==='number'?value.toLocaleString(locale()):esc(value);
